{
  "table": {
    "name": "rulings",
    "purpose": "Official Magic: The Gathering card rulings (rules clarifications/Oracle rulings issued by Wizards of the Coast), one row per ruling attached to a specific card printing. Evidence: ruling texts use MTG rules vocabulary (cycling, totem armor, Adventure spells, planeswalkers, unearth, Slivers), the uuid column joins to cards.uuid, and the sibling tables (cards, sets, legalities, foreign_data, set_translations) match the MTGJSON database layout. The same ruling text repeats across rows because it is attached to every printing of the same card, which is why text and date have low uniqueness relative to row count."
  },
  "columns": {
    "date": {
      "role": "date",
      "name": "ruling_date",
      "description": "Date the ruling was issued/published, in YYYY-MM-DD form. Only 109 distinct dates over ~88k rows, with large batches (e.g. 6,334 rulings on 2004-10-04, 4,123 on 2021-02-05) corresponding to bulk ruling releases that accompany Comprehensive Rules updates; range 2004-10-04 to 2021-02-05.",
      "status": "resolved"
    },
    "id": {
      "role": "identifier",
      "name": "ruling_id",
      "description": "Surrogate primary key: a dense sequential integer (1 to 87,769, no nulls, fully unique) identifying each ruling row. Carries no business meaning beyond row identity.",
      "status": "resolved"
    },
    "text": {
      "role": "free_text",
      "name": "ruling_text",
      "description": "Full text of the official ruling explaining how the referenced card's abilities work or interact with the rules (e.g. 'Cycling is an activated ability...', 'Totem armor has no effect if the enchanted permanent is put into a graveyard...'). 19,593 distinct texts across 87,769 rows because the same ruling is stored once per printing of the card.",
      "status": "resolved"
    },
    "uuid": {
      "role": "foreign_key",
      "name": "card_uuid",
      "description": "UUID of the card printing the ruling applies to; foreign key to cards.uuid (many-to-one, up to ~27 rulings per card). This is MTGJSON's per-printing card identifier, not a ruling identifier — the same ruling text/date recurs under the uuids of different printings of the same card.",
      "status": "resolved"
    }
  }
}
